const elements=[['H','Hydrogen'],['He','Helium'],['Li','Lithium'],['Be','Beryllium'],['B','Boron'],['C','Carbon'],['N','Nitrogen'],['O','Oxygen'],['F','Fluorine'],['Ne','Neon'],['Na','Sodium'],['Mg','Magnesium'],['Al','Aluminium'],['Si','Silicon'],['P','Phosphorus'],['S','Sulfur'],['Cl','Chlorine'],['Ar','Argon'],['K','Potassium'],['Ca','Calcium']];
function shells(atomic){let left=atomic,shells=[];for(const capacity of [2,8,8,2]){if(left<=0)break;let n=Math.min(capacity,left);shells.push(n);left-=n}return shells}
function elementInfo(i){const e=elements[i], n=i+1,s=shells(n);return `<span class="tag">ELEMENT ${n}</span><h2 style="margin-top:15px">${e[1]} <span style="color:var(--blue)">(${e[0]})</span></h2><p class="muted">Atomic number: <b>${n}</b> • Electrons in a neutral atom: <b>${n}</b></p><div class="atom-display">${s.map((num,j)=>`<div class="electron-ring" style="width:${100+j*47}px;height:${100+j*47}px"><span style="transform:rotate(${j*40}deg)"></span></div>`).join('')}<div class="atom-center">${e[0]}</div></div><div class="notice">Simplified electron-shell distribution: ${s.join(' – ')}</div>`}
