function availableQuestions(){return [...starterQuestions,...remoteQuestions].filter(q=>q.board===state.quiz.board&&q.grade===state.quiz.grade&&q.subject===state.quiz.subject&&q.chapter===state.quiz.chapter)}
function quizPage(){const groups=[...new Set([...starterQuestions,...remoteQuestions].map(q=>q.board))];const all=[...starterQuestions,...remoteQuestions].filter(q=>q.board===state.quiz.board);const gradeSet=[...new Set(all.map(q=>q.grade))].sort((a,b)=>Number(a)-Number(b));const available=all.filter(q=>q.grade===state.quiz.grade);const subs=[...new Set(available.map(q=>q.subject))];const chapters=[...new Set(available.filter(q=>q.subject===state.quiz.subject).map(q=>q.chapter))];const qs=availableQuestions(),q=qs[state.quiz.i];let gameplay='';
if(state.quiz.completed){const correct=qs.filter((q,i)=>String(state.quiz.answers[i]??'').trim().toLowerCase()===String(q.answer).trim().toLowerCase()).length;const pct=qs.length?Math.round(correct/qs.length*100):0;const missed=qs.filter((x,i)=>String(state.quiz.answers[i]??'').trim().toLowerCase()!==String(x.answer).trim().toLowerCase());gameplay=`<div class="card"><div class="row" style="gap:30px"><div class="score-circle">${pct}%</div><div><span class="tag">PRACTICE REVIEW</span><h2 style="margin:12px 0">${correct} / ${qs.length} correct</h2><p class="muted">This is practice feedback, not a certified exam score.</p></div></div><div class="divider"></div><h3>Your answer review</h3>${qs.map((x,i)=>{let ok=String(state.quiz.answers[i]??'').trim().toLowerCase()===String(x.answer).trim().toLowerCase();return `<div style="padding:16px 0;border-bottom:1px solid var(--border)"><span class="tag" style="background:${ok?'#e9fbf1':'#fff2e7'}">${ok?'✓ Correct':'Review concept'}</span><p style="margin:10px 0 6px"><b>${h(x.text)}</b></p><p class="thin muted">Your answer: ${h(state.quiz.answers[i]??'—')} · Correct answer: ${h(x.answer)}</p><p class="thin">${h(x.explanation)}</p></div>`}).join('')}<div class="notice"><b>Vision Smart Path</b><br>${missed.length?`Revise: ${[...new Set(missed.map(x=>h(x.tag)))].join(', ')}. Try similar questions after reviewing each explanation.`:'Great progress on these topics. Continue with another chapter to keep learning.'}</div><div class="row">${c('Smart Path','/smart-path','ghost')}<button type="button" class="pill primary" id="quiz-retry">Try Again ↻</button></div></div>`}
else if(q){const progress=(state.quiz.i/qs.length)*100;gameplay=`<div class="card"><div class="row space"><span class="question-tag">QUESTION ${state.quiz.i+1} OF ${qs.length} • ${h(q.tag)}</span><span class="tag">Practice</span></div><div style="height:7px;background:#e4edfc;border-radius:9px;margin:20px 0 30px"><div style="height:7px;border-radius:9px;background:var(--blue);width:${progress}%"></div></div><h2 style="font-size:26px;letter-spacing:-.02em">${h(q.text)}</h2>${q.kind==='mcq'||q.kind==='tf'?q.options.map(opt=>`<button type="button" class="quiz-option ${state.quiz.answers[state.quiz.i]===opt?'selected':''}" data-answer="${h(opt)}"><span style="width:23px;height:23px;border:1px solid #bed0ec;border-radius:50%;display:grid;place-items:center">${state.quiz.answers[state.quiz.i]===opt?'✓':'○'}</span>${h(opt)}</button>`).join(''):`<div class="field"><label for="numeric-answer">Your answer</label><input id="numeric-answer" type="text" inputmode="decimal" autocomplete="off" placeholder="Enter your answer" value="${h(state.quiz.answers[state.quiz.i]??'')}"></div>`}<div class="row space space-top">${state.quiz.i?'<button type="button" id="quiz-prev" class="pill ghost">← Previous</button>':'<span></span>'}<button type="button" id="quiz-next" class="pill primary">${state.quiz.i===qs.length-1?'Finish Practice':'Next Question →'}</button></div></div>`}
else gameplay=`<div class="card"><h3>No published questions in this selection yet</h3><p class="muted">Choose another foundation practice selection. Board-specific curriculum content will appear after teachers verify and publish it.</p></div>`;
return `${openTitle('Vision Quiz Club','Learn • Practice • Review • Improve. Original starter questions and teacher-published practice items.','Quiz Club')}<section class="soft"><div class="container"><div class="grid grid-2" style="grid-template-columns:340px 1fr;align-items:start"><aside class="card"><span class="tag">SELECT YOUR PRACTICE</span><h3 style="margin-top:14px">Board → Class → Subject → Chapter</h3><div class="field" style="margin-top:18px"><label for="quiz-board">Board / Practice Collection</label><select id="quiz-board"><option value="FOUNDATION">General Foundation (Starter)</option>${['CBSE','CGBSE','ICSE'].map(b=>`<option value="${b}" ${state.quiz.board===b?'selected':''}>${b}${groups.includes(b)?'':' — Awaiting verified content'}</option>`).join('')}</select></div><div class="field" style="margin-top:14px"><label for="quiz-grade">Class</label><select id="quiz-grade">${(gradeSet.length?gradeSet:['1','5','6','8','10']).map(g=>`<option value="${g}" ${state.quiz.grade===g?'selected':''}>Class ${g}</option>`).join('')}</select></div><div class="field" style="margin-top:14px"><label for="quiz-subject">Subject</label><select id="quiz-subject">${(subs.length?subs:['Mathematics','Science']).map(s=>`<option value="${h(s)}" ${state.quiz.subject===s?'selected':''}>${h(s)}</option>`).join('')}</select></div><div class="field" style="margin-top:14px"><label for="quiz-chapter">Topic / Chapter</label><select id="quiz-chapter">${(chapters.length?chapters:['Select a topic']).map(s=>`<option value="${h(s)}" ${state.quiz.chapter===s?'selected':''}>${h(s)}</option>`).join('')}</select></div><div class="notice warn">Starter questions are general foundation practice, not verified coverage of any board's complete syllabus.</div></aside><div>${gameplay}</div></div></div></section>`}
function smartPathPage(){let report=null;try{report=JSON.parse(localStorage.getItem('sv-last-practice')||'null')}catch{}return `${openTitle('Vision Smart Path','Personalized, topic-wise practice recommendations based on your answered questions.','Smart Path')}<section class="soft"><div class="container content-pane"><div class="card"><span class="tag">YOUR PRACTICE PLAN</span>${!report?`<div class="panel-empty"><div class="emoji">🧭</div><h3>Your learning path starts with practice.</h3><p>Complete a quiz to generate a topic-wise review checklist from actual answers.</p>${c('Start a Quiz','/quiz')}</div>`:`<h2 style="margin-top:15px">Your latest practice review</h2><p class="muted">${h(report.subject)} • Class ${h(report.grade)} • ${fmt(report.at)}</p><div class="grid grid-2"><div class="metric"><b>${report.correct}/${report.total}</b><span>Correct answers</span></div><div class="metric"><b>${Math.round(report.correct/report.total*100)}%</b><span>Practice score</span></div></div><h3 style="margin-top:25px">${report.mistakes.length?'Topics to revisit':'Topics practiced successfully'}</h3><ul class="listcheck">${(report.mistakes.length?report.mistakes:report.concepts).map(x=>`<li>${h(x)}</li>`).join('')}</ul><div class="notice">Revise the explanation of each missed question, work through one similar problem, then try again. Recommendations are based on question tags—not AI diagnosis.</div>${c('Continue Practice','/quiz')}`}</div></div></section>`}
function formPage(type){const isAdmission=type==='admissions',isDemo=type==='demo',title=isAdmission?'Start your admission enquiry':'Book a free demo class';const fields=isAdmission?`<div class="field"><label for="f-student">Student name *</label><input id="f-student" name="studentName" maxlength="80" required autocomplete="name"></div><div class="field"><label for="f-class">Class *</label><select id="f-class" name="grade" required><option value="">Select class</option>${grades.map(g=>`<option value="${g}">Class ${g}</option>`).join('')}</select></div><div class="field"><label for="f-school">School name (optional)</label><input id="f-school" name="school" maxlength="100"></div><div class="field"><label for="f-course">Course *</label><select id="f-course" name="course" required><option value="">Select course</option>${courses.map(x=>`<option value="${x.key}">${x.title} • ${x.subtitle}</option>`).join('')}</select></div><div class="field"><label for="f-batch">Preferred batch</label><input id="f-batch" name="preferredBatch" maxlength="80" placeholder="Optional preference; no timings promised"></div>`:`<div class="field"><label for="f-class">Class *</label><select id="f-class" name="grade" required><option value="">Select class</option>${grades.map(g=>`<option value="${g}">Class ${g}</option>`).join('')}</select></div><div class="field"><label for="f-subject">Subject *</label><select id="f-subject" name="subject" required><option value="">Select subject</option><option>Mathematics</option><option>Science</option><option>All Subjects</option></select></div><div class="field full"><label for="f-slot">Available demo slot *</label><select id="f-slot" name="slotId" required><option value="">${state.backend?'Loading published slots…':'Connect Firebase to load real slots'}</option></select><p class="muted thin">Submitting a request does not confirm a booking. Confirmations require administrator approval.</p></div>`;
return `${openTitle(title,isAdmission?'Tell us about your learning needs. Our team can review your enquiry once the secure backend is configured.':'Choose a real, administrator-created availability slot. No invented timings.','Admissions')}<section class="soft"><div class="container split" style="align-items:start"><div><div class="kicker">${isAdmission?'ADMISSIONS':'DEMO CLASS'}</div><h2>${isAdmission?'A great learning journey begins with a conversation.':'See how concept-based learning works.'}</h2><p class="muted">At SAURABH’S VISION, learning begins with curiosity and an understanding of each student's needs.</p><ul class="listcheck"><li>Classes 1–5: all subjects</li><li>Classes 6–10: mathematics and science</li><li>Special support for Classes 5, 8 and 10</li><li>Location: Near Mahamaya Temple, Bhanpuri, Raipur</li></ul><div class="notice warn">For students under 18, a parent or guardian should complete and approve the enquiry.</div></div><div class="form-card"><h3>${isAdmission?'Admission Enquiry Form':'Demo Class Request'}</h3><p class="muted thin">Required fields are marked with *.</p><form id="${type}-form"><input type="text" name="website" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-10000px" ><div class="formgrid">${fields}<div class="field"><label for="f-guardian">Parent / guardian name *</label><input id="f-guardian" name="guardianName" maxlength="80" required></div><div class="field"><label for="f-contact">Guardian contact number *</label><input id="f-contact" name="contact" inputmode="tel" autocomplete="tel" pattern="[0-9+() -]{8,18}" maxlength="18" required></div><div class="field full"><label for="f-message">Additional message (optional)</label><textarea id="f-message" name="message" maxlength="700" placeholder="Share a question or learning goal"></textarea></div><div class="full"><label class="thin"><input type="checkbox" name="consent" required> I am the parent/guardian or have their permission to submit this request. I agree to the contact and privacy notice.</label></div><div class="full"><button class="pill primary" type="submit" ${!state.backend?'disabled title="Firebase configuration required"':''}>${isAdmission?'Send Enquiry':'Request Demo Slot'} →</button><div id="form-status" aria-live="polite"></div></div></div></form>${!state.backend?'<div class="notice warn">Secure online submissions are not active yet. Configure Firebase in <code>firebase-config.js</code>; this form intentionally does not pretend to save your data.</div>':''}</div></div></section>`}
function loginPage(){return `${openTitle('Welcome to My Vision','Secure access for students, parents, teachers and administrators.','Student Portal')}<section class="soft"><div class="container content-pane"><div class="grid grid-2"><div class="form-card"><span class="tag">SECURE SIGN IN</span><h3 style="margin-top:14px">Your learning account</h3>${state.user?`<div class="notice success">Signed in as ${h(state.user.email||'account holder')} • ${h(state.role||'Account')}</div>${c('Open My Dashboard','/dashboard')}<button type="button" class="pill ghost" id="sign-out" style="margin-top:12px">Sign out</button>`:`<form id="login-form"><div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="username"></div><div class="field" style="margin-top:16px"><label>Password</label><input name="password" type="password" required autocomplete="current-password" minlength="6"></div><button class="pill primary" type="submit" style="margin-top:20px" ${!state.backend?'disabled':''}>Sign In →</button><div id="login-status" aria-live="polite"></div></form>`}${!state.backend?'<div class="notice warn">Authentication is inactive until Firebase is configured. No demo accounts or fake login.</div>':''}</div><div class="card"><div class="feature-icon">🔒</div><h3 style="margin-top:15px">Privacy-first learning</h3><ul class="listcheck"><li>Student practice records stay private.</li><li>Parents see only properly linked children.</li><li>Teachers have restricted subject access.</li><li>Administrators manage approved content and accounts.</li></ul><div class="notice">Accounts are provisioned by the institute after appropriate guardian consent. No public registration of children's accounts.</div></div></div></div></section>`}
function dashboardPage(kind){const role=state.role;const titleMap={student:'My Vision Dashboard',parent:'Parent Portal',teacher:'Teacher Dashboard',admin:'Admin Control Centre'};let intended=kind||({student:'student',parent:'parent',teacher:'teacher',admin:'admin'}[role]||'student');let title=titleMap[intended]||titleMap.student;const roleMismatch=kind&&role!==kind&&role!=='admin';return `${openTitle(title,'Private educational tools with role-based data access.','Portal')}<section class="soft"><div class="container">${!state.user?`<div class="card content-pane panel-empty"><div class="emoji">🔐</div><h3>Sign in to access this portal</h3><p>Real accounts and secure authorization are required.</p>${c('Sign In','/login')}</div>`:roleMismatch?`<div class="notice error">This account is not authorized to open the ${h(kind)} portal.</div>`:`<div class="dashboard-grid"><aside class="side-card"><div class="user-circle">${h((state.user.email||'V').charAt(0).toUpperCase())}</div><h3 style="margin-top:15px">${h(state.user.email||'Account')}</h3><span class="tag">${h(role||'Account')}</span><div class="divider"></div><p class="muted thin">Records are loaded only from the connected database.</p><button id="dashboard-refresh" class="pill ghost small">Refresh Data ↻</button><button id="sign-out" class="pill ghost small" style="margin-top:10px">Sign out</button></aside><div id="dashboard-content"><div class="card"><div class="spinner"></div> Loading your authorized records…</div></div></div>`}</div></section>`}
function resultsPage(){return `${openTitle('Results & Achievements','Only verified, permission-approved achievements are displayed here.','Results')}<section class="soft"><div class="container"><div id="results-content"><div class="card panel-empty"><div class="emoji">🏅</div><h3>No public results have been published.</h3><p>Approved achievements will appear once verified by the administrator.</p></div></div></div></section>`}
function galleryPage(){return `${openTitle('Life at Saurabh’s Vision','Classroom activities, learning events and approved moments, shared with permission.','Gallery')}<section class="soft"><div class="container"><div id="gallery-content"><div class="grid grid-3">${['Classroom activities','Science exploration','Celebrations & learning'].map(x=>`<div class="gallery-placeholder"><div><div class="emoji">📷</div><b>${x}</b><p class="thin">Photos will appear after permission and admin approval.</p></div></div>`).join('')}</div></div></div></section>`}
function contactPage(){const addr='Near Mahamaya Temple, Bhanpuri, Raipur, Chhattisgarh, India';return `${openTitle('Let’s connect','Questions about courses, admissions or learning? We would love to hear from you.','Contact')}<section><div class="container split"><div><div class="kicker">VISIT OUR INSTITUTE</div><h2>Find us in <span style="color:var(--blue)">Raipur.</span></h2><div class="card"><h3>📍 SAURABH’S VISION™</h3><p class="muted">${addr}</p><p class="thin muted">Phone, WhatsApp, email and institute timings are displayed only after an administrator enters verified details.</p><div id="contact-details"></div><div class="row">${c('Admission Enquiry →','/admissions')}${c('Book Demo','/demo','ghost')}</div></div></div><div class="contact-map"><span style="font-size:58px">📍</span><h3>Bhanpuri, Raipur</h3><p class="muted">Near Mahamaya Temple</p><a target="_blank" rel="noopener noreferrer" class="pill primary" href="https://www.google.com/maps/search/?api=1&query=Near+Mahamaya+Temple+Bhanpuri+Raipur">Open Maps Search ↗</a><p class="thin muted">Map search is not a verified precise pin.</p></div></div></section>`}
function materialsPage(type){const titles={materials:'Digital Classroom & Study Materials',homework:'Homework & Assignments',tests:'Online Tests',doubts:'Vision Doubt Drop'};let contents='';if(type==='doubts'){contents=`${state.user&&state.role==='student'?`<form class="form-card" id="doubt-form"><div class="formgrid"><div class="field"><label>Subject *</label><select name="subjectKey" required><option value="">Choose subject</option><option value="Mathematics">Mathematics</option><option value="Science">Science</option></select></div><div class="field"><label>Chapter / Topic *</label><input name="chapter" maxlength="90" required></div><div class="field full"><label>Your question *</label><textarea name="question" maxlength="2000" required></textarea></div><div class="field full"><label>Optional question image (JPEG / PNG / WebP, max 5 MB)</label><input name="image" type="file" accept="image/jpeg,image/png,image/webp"></div><div class="full"><button type="submit" class="pill primary">Submit Doubt</button><div id="doubt-status" aria-live="polite"></div></div></div></form><div id="my-doubts" style="margin-top:25px"></div>`:`<div class="card panel-empty"><div class="emoji">💬</div><h3>Ask. Understand. Improve.</h3><p>Sign in with an authorized student account to submit a doubt and receive a teacher's reply.</p>${c('Student Sign In','/login')}</div>`}`}
 else contents=`<div class="card"><div class="icon-title"><div class="feature-icon">${type==='materials'?'📖':type==='homework'?'📝':'🧠'}</div><div><h3>${titles[type]}</h3><p class="muted thin" style="margin-bottom:0">Only authorized, teacher-published ${type==='materials'?'learning materials':type==='homework'?'assignments':'assessments'} are shown.</p></div></div><div id="content-records" class="panel-empty"><div class="emoji">${type==='tests'?'🧩':'📂'}</div><p>No published records currently available to this visitor.</p>${type==='tests'?c('Try Foundation Practice','/quiz'):c('Go to Student Portal','/login')}</div></div>`;
 return `${openTitle(titles[type],'A simple, organized learning environment.','Learning')}<section class="soft"><div class="container content-pane">${contents}</div></section>`}
function legalPage(type){return `${openTitle(type==='privacy'?'Privacy Policy':'Terms & Conditions','Review this owner-editable draft before making the website public.','Legal')}<section><div class="container content-pane readable"><div class="notice warn"><strong>Draft for institute review:</strong> This page must be reviewed and updated for applicable law, actual service providers, retention periods and institute contact information before launch.</div>${type==='privacy'?`<h2>Information collected</h2><p>When configured, this site may process admission enquiries, guardian contact details, student learning accounts, quiz practice records, and student-submitted questions. Information is used for education-related services, enquiries and communication requested by a parent or guardian.</p><h2>Children and guardians</h2><p>Student accounts should be created only with suitable parental or guardian consent. Parent accounts should be linked only after identity and relationship verification. Public results or student photographs are never published without applicable permission.</p><h2>Storage and access</h2><p>Data is hosted by the institute's configured service provider. Access is controlled by roles and database security rules. Retention and deletion practices must be defined by the owner. Questions about personal data should be directed to the institute's verified contact details.</p>`:`<h2>Use of the website</h2><p>Public educational examples are intended to support learning. They do not replace individual academic guidance or guarantee examination results.</p><h2>Accounts and materials</h2><p>Users must only access accounts and learning materials authorized for them. The institute retains responsibility for verifying content rights and responding to requests concerning accounts.</p><h2>Admissions and demo requests</h2><p>Submitting an online request is not an admission offer or a confirmed demo booking. The institute must contact the guardian to complete any arrangement.</p>`}</div></section>`}
function niceDate(v){return v?.seconds?fmt(v.seconds*1000):v?fmt(v):'—'}
function itemRows(items,keys){return `<div class="table-wrap"><table class="info-table"><thead><tr>${keys.map(x=>`<th>${h(x[1])}</th>`).join('')}</tr></thead><tbody>${items.map(x=>`<tr>${keys.map(([k])=>`<td>${h(x[k]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function adminPanel(role,records){const admin=role==='admin';let content='';if(admin){const apps=records.admissions||[],books=records.demoBookings||[],slots=records.demoSlots||[];
 const table=(rows,kind)=>`<div class="table-wrap"><table class="info-table"><thead><tr><th>Reference</th><th>Details</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="thin">${h(x.id.slice(0,10))}</td><td><b>${h(x.guardianName)}</b><br><small>${h(x.studentName||x.subject||'')} ${h(x.grade?' • Class '+x.grade:'')}<br>${h(x.contact)}</small></td><td><span class="tag">${h(x.status)}</span></td><td><div class="row">${(kind==='admissions'?['new','contacted','demo scheduled','admitted','closed']:['requested','closed']).filter(z=>z!==x.status).map(z=>`<button class="chip" data-admin-status="${kind}|${h(x.id)}|${z}">${z}</button>`).join('')}${kind==='demoBookings'&&x.status==='requested'?`<button class="chip" data-confirm-booking="${h(x.id)}">Confirm (Server)</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`;
content=`<div class="grid grid-4">${[['New Enquiries',apps.filter(x=>x.status==='new').length],['Demo Requests',books.filter(x=>x.status==='requested').length],['Available Slots',slots.filter(x=>x.active).length],['Published Quiz Items',(records.quizQuestions||[]).filter(x=>x.published).length]].map(x=>`<div class="metric"><b>${x[1]}</b><span>${x[0]}</span></div>`).join('')}</div>
<div class="card" style="margin-top:22px"><h3>Admission Enquiries</h3>${apps.length?table(apps,'admissions'):'<p class="muted thin">No admissions submitted.</p>'}</div>
<div class="card" style="margin-top:22px"><h3>Demo Booking Requests</h3>${books.length?table(books,'demoBookings'):'<p class="muted thin">No demo requests received.</p>'}</div>
<div class="grid grid-2" style="margin-top:22px"><div class="card"><h3>Add real demo availability</h3><form id="slot-form"><div class="field"><label>Start date & time</label><input type="datetime-local" name="startAt" required></div><div class="field" style="margin-top:12px"><label>Max confirmed bookings</label><input name="capacity" type="number" min="1" max="100" value="1" required></div><button class="pill primary small" style="margin-top:14px">Add Slot</button></form>${slots.length?`<div class="divider"></div>${slots.map(x=>`<p class="thin">${h(x.startAt)} — ${h(x.bookedCount||0)}/${h(x.capacity)} booked</p>`).join('')}`:''}</div><div class="card"><h3>Verified contact details</h3><form id="settings-form"><div class="field"><label>Phone (optional)</label><input name="phone" value="${h(state.settings?.phone||'')}" maxlength="20"></div><div class="field" style="margin-top:11px"><label>WhatsApp (optional)</label><input name="whatsapp" value="${h(state.settings?.whatsapp||'')}" maxlength="20"></div><div class="field" style="margin-top:11px"><label>Email (optional)</label><input name="email" type="email" value="${h(state.settings?.email||'')}" maxlength="100"></div><div class="field" style="margin-top:11px"><label>Institute timings (optional)</label><input name="timings" value="${h(state.settings?.timings||'')}" maxlength="120"></div><button class="pill primary small" style="margin-top:14px">Save Contact Details</button></form></div></div>`}
 const teachersAllowed=admin||role==='teacher';if(teachersAllowed){content+=`<div class="grid grid-2" style="margin-top:22px"><div class="card"><span class="tag">EDUCATION CMS</span><h3 style="margin-top:10px">Publish a quiz question</h3><form id="add-question-form"><div class="field"><label>Collection</label><select name="board"><option value="FOUNDATION">Foundation Practice</option><option value="CBSE">CBSE (verified only)</option><option value="CGBSE">CGBSE (verified only)</option><option value="ICSE">ICSE (verified only)</option></select></div><div class="formgrid" style="margin-top:10px"><div class="field"><label>Class</label><select name="grade">${grades.map(g=>`<option>${g}</option>`).join('')}</select></div><div class="field"><label>Subject</label><select name="subject"><option>Mathematics</option><option>Science</option></select></div><div class="field full"><label>Topic / Chapter</label><input name="chapter" maxlength="80" required></div><div class="field full"><label>Question</label><textarea name="text" maxlength="500" required></textarea></div><div class="field full"><label>MCQ choices (each on a new line, exactly four)</label><textarea name="options" maxlength="600" placeholder="Choice 1&#10;Choice 2&#10;Choice 3&#10;Choice 4" required></textarea></div><div class="field"><label>Correct answer (exact choice)</label><input name="answer" maxlength="150" required></div><div class="field"><label>Concept tag</label><input name="tag" maxlength="80" required></div><div class="field full"><label>Explanation</label><textarea name="explanation" maxlength="500" required></textarea></div></div><label class="thin"><input name="published" type="checkbox"> Publish immediately (teacher-verified content only)</label><br><button class="pill primary small" style="margin-top:15px">Save Question</button></form></div><div class="card"><span class="tag">CONTENT MANAGEMENT</span><h3 style="margin-top:10px">Publish study material / homework</h3><form id="add-content-form"><div class="field"><label>Content type</label><select name="type"><option value="studyMaterials">Study material</option><option value="homework">Homework</option>${admin?'<option value="announcements">Announcement</option><option value="gallery">Gallery URL (permission confirmed)</option><option value="results">Verified achievement (consent confirmed)</option>':''}</select></div><div class="field" style="margin-top:10px"><label>Title</label><input name="title" maxlength="120" required></div><div class="formgrid" style="margin-top:10px"><div class="field"><label>Class</label><select name="grade">${grades.map(g=>`<option>${g}</option>`).join('')}</select></div><div class="field"><label>Subject</label><select name="subject"><option>Mathematics</option><option>Science</option><option>All Subjects</option></select></div><div class="field full"><label>Optional authorized HTTPS content URL</label><input name="url" type="url" maxlength="500" placeholder="https://..."></div><div class="field full"><label>Description</label><textarea name="description" maxlength="700"></textarea></div></div><label class="thin"><input type="checkbox" name="published" checked> Publish</label><br><button class="pill primary small" style="margin-top:15px">Save Content</button></form><div class="notice warn">Publish only material you own or are authorized to share. Student achievements need explicit publication consent.</div></div></div>`;
 const doubts=records.doubts||[];content+=`<div class="card" style="margin-top:22px"><h3>Student Doubt Requests</h3>${doubts.length?doubts.map(x=>`<div style="border-top:1px solid var(--border);padding:20px 0"><div class="row space"><span class="tag">${h(x.subjectKey)} • ${h(x.status)}</span><small class="muted">${h(x.chapter)}</small></div><p><b>${h(x.question)}</b></p>${x.answer?`<p class="muted">Current answer: ${h(x.answer)}</p>`:''}<form data-answer-doubt="${h(x.id)}"><div class="field"><label>Teacher response</label><textarea name="answer" maxlength="4000" required>${h(x.answer||'')}</textarea></div><button class="pill primary small" style="margin-top:9px">Post Answer</button></form></div>`).join(''):'<p class="muted thin">No accessible doubt requests.</p>'}</div>`;
 }
 return content||'<div class="card">Your role has no admin controls.</div>'}
async function fetchDashboard(){if(!state.user||!state.backend)return;const uid=state.user.uid,role=state.role;const el=document.querySelector('#dashboard-content');if(!el)return;
 try{if(role==='student'){
 const [profile,attempts,doubts]=await Promise.all([state.backend.profile(uid),state.backend.myAttempts(uid),state.backend.myDoubts(uid)]);let hw=[];try{if(profile?.grade)hw=await state.backend.assignedWork(profile.grade)}catch{}
 el.innerHTML=`<div class="grid grid-3"><div class="metric"><b>${attempts.length}</b><span>Practice sessions saved</span></div><div class="metric"><b>${doubts.length}</b><span>Doubt requests</span></div><div class="metric"><b>${hw.length}</b><span>Class homework items</span></div></div><div class="card" style="margin-top:22px"><h3>Recent practice</h3>${attempts.length?itemRows(attempts.slice(0,12),[['subject','Subject'],['grade','Class'],['correct','Correct'],['total','Total']]):'<p class="muted thin">No saved practice yet.</p>'}${c('Take a Quiz →','/quiz')}</div><div class="grid grid-2" style="margin-top:22px"><div class="card"><h3>Homework</h3>${hw.length?hw.map(x=>`<p>📝 ${h(x.title)} • ${h(x.subject)}</p>`).join(''):'<p class="muted thin">No assigned homework currently.</p>'}${c('View Homework','/homework','ghost')}</div><div class="card"><h3>My Questions</h3>${doubts.length?doubts.map(x=>`<p>💬 ${h(x.chapter)} <span class="tag">${h(x.status)}</span></p>`).join(''):'<p class="muted thin">No doubts submitted.</p>'}${c('Doubt Drop','/doubts','ghost')}</div></div>`}
 else if(role==='parent'){const links=await state.backend.parentLinks(uid);let boxes=[];for(const link of links){const [profile,attempts]=await Promise.all([state.backend.profile(link.studentId),state.backend.myAttempts(link.studentId)]);boxes.push(`<article class="card"><span class="tag">LINKED CHILD</span><h3 style="margin-top:12px">${h(profile?.displayName||'Student')}</h3><p>Class ${h(profile?.grade||'—')} • ${attempts.length} practice sessions</p>${attempts.length?`<p class="muted">Latest practice: ${h(attempts[0].subject)} (${h(attempts[0].correct)}/${h(attempts[0].total)})</p>`:''}</article>`)}el.innerHTML=boxes.length?`<div class="grid grid-2">${boxes.join('')}</div>`:`<div class="card panel-empty"><div class="emoji">👨‍👩‍👧</div><h3>No verified child link yet</h3><p>An administrator must verify guardianship before linking a child's private profile.</p></div>`}
 else if(role==='teacher'||role==='admin'){let records={};if(role==='admin'){const keys=['admissions','demoBookings','demoSlots','quizQuestions','doubts'];await Promise.all(keys.map(async k=>{records[k]=await state.backend.adminList(k)}))}else{const assigned=await state.backend.teacherAssignments(uid);records.doubts=await state.backend.teacherDoubts(assigned);}
 el.innerHTML=adminPanel(role,records)}else el.innerHTML='<div class="card">This account has no assigned portal role. Contact the institute administrator.</div>';
 }catch(err){el.innerHTML=`<div class="notice error">Could not load authorized records: ${h(err.message)}</div>`}}
async function loadRemote(){if(!state.backend)return;try{const raw=await state.backend.getQuestions();remoteQuestions=raw.filter(x=>['FOUNDATION','CBSE','CGBSE','ICSE'].includes(x.board)&&Array.isArray(x.options)&&x.options.length>=2&&typeof x.answer==='string'&&x.kind==='mcq');}catch(err){console.warn('Practice bank unavailable',err)}
 try{state.settings=await state.backend.settings()}catch{};
 if(state.route==='/quiz')render();
}
async function loadPublicPage(){if(!state.backend)return;
 try{if(state.route==='/demo'){const slots=await state.backend.slots();const select=document.querySelector('#f-slot');if(select)select.innerHTML=`<option value="">Select a published slot</option>${slots.map(x=>`<option value="${h(x.id)}">${h(new Date(x.startAt).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}))} • ${h(x.capacity-x.bookedCount)} place(s)</option>`).join('')}`}
 if(state.route==='/results'||state.route==='/gallery'){const name=state.route.slice(1),items=await state.backend.publicItems(name),el=document.querySelector(`#${name}-content`);if(el&&items.length){el.innerHTML=`<div class="grid grid-3">${items.map(x=>`<article class="card">${x.url&&safeUrl(x.url)?`<a href="${h(x.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${h(x.title)}">${name==='gallery'?`<img src="${h(x.url)}" alt="${h(x.title)}" style="width:100%;height:180px;object-fit:cover;border-radius:13px" loading="lazy">`:'<span class="feature-icon">↗</span>'}</a>`:'<div class="feature-icon">🏅</div>'}<h3 style="margin-top:17px">${h(x.title)}</h3><p class="muted thin">${h(x.description||'')}</p><span class="tag">Administrator approved</span></article>`).join('')}</div>`}}
 if(state.route==='/contact'){const el=document.querySelector('#contact-details');if(el){const s=state.settings||await state.backend.settings();const phone=String(s.phone||'').replace(/[^0-9+]/g,''),wa=String(s.whatsapp||'').replace(/\D/g,'');el.innerHTML=`${phone?`<p>📞 <a href="tel:${h(phone)}">${h(phone)}</a></p>`:''}${s.email?`<p>✉️ <a href="mailto:${encodeURIComponent(s.email)}">${h(s.email)}</a></p>`:''}${s.timings?`<p>🕓 ${h(s.timings)}</p>`:''}${wa?`<p><a class="pill ghost small" target="_blank" rel="noopener noreferrer" href="https://wa.me/${h(wa)}">WhatsApp Enquiry ↗</a></p>`:''}`}}
 if(state.route==='/materials'){const items=await state.backend.publicItems('studyMaterials'),el=document.querySelector('#content-records');if(el&&items.length)el.innerHTML=items.map(x=>`<p><b>${h(x.title)}</b> · ${h(x.subject)} ${x.url&&safeUrl(x.url)?`<a class="tag" href="${h(x.url)}" target="_blank" rel="noopener noreferrer">View ↗</a>`:''}<br><small>${h(x.description||'')}</small></p>`).join('')}
 if(state.route==='/homework'&&state.user&&state.role==='student'){const pr=await state.backend.profile(state.user.uid),items=pr?.grade?await state.backend.assignedWork(pr.grade):[],el=document.querySelector('#content-records');if(el&&items.length)el.innerHTML=items.map(x=>`<p><b>${h(x.title)}</b> • ${h(x.subject)}<br><small>${h(x.description||'')}</small></p>`).join('')}
 if(state.route==='/doubts'&&state.user&&state.role==='student')await loadDoubts();
 }catch(err){console.warn('Page data unavailable',err)}
}
async function loadDoubts(){const el=document.querySelector('#my-doubts');if(!el||!state.backend||!state.user)return;try{let rows=await state.backend.myDoubts(state.user.uid);el.innerHTML=rows.length?`<h3>My doubt history</h3>${rows.map(x=>`<div class="card" style="margin-bottom:12px"><span class="tag">${h(x.status)}</span><h3 style="margin:13px 0">${h(x.chapter)}</h3><p>${h(x.question)}</p>${x.answer?`<div class="notice success"><b>Teacher response:</b> ${h(x.answer)}</div>`:''}${x.status==='answered'?`<button type="button" class="chip" data-resolve-doubt="${h(x.id)}">Mark resolved</button>`:''}</div>`).join('')}`:'<div class="notice">No doubt requests submitted yet.</div>'}catch(err){el.innerHTML=`<div class="notice error">${h(err.message)}</div>`}}
function safeUrl(s){try{const x=new URL(s);return x.protocol==='https:'}catch{return false}}
function layout(content){const navLinks=navigation.map(([to,k])=>a(to,tr(k),state.route===to?'active':'')).join('')+`<a class="sprint-nav" href="./study-sprint/index.html">🎯 Daily Sprint</a>`;let wa=String(state.settings?.whatsapp||'').replace(/\D/g,'');return `<div class="wave"></div><div class="topbar"><div class="container"><span>📍 ${tr('location')} &nbsp;&nbsp; • &nbsp;&nbsp; ${tr('tagline')}</span><span>✨ Education with purpose</span></div></div><header class="header"><div class="container navwrap"><a href="#/" class="brand" aria-label="SAURABH'S VISION home">${brand}</a><nav class="navlinks" aria-label="Main navigation">${navLinks}</nav><div class="navright"><button id="lang-switch" type="button" class="lang-btn" aria-label="Change language">${state.lang==='en'?'हिन्दी':'English'}</button>${c(tr('login'),'/login','ghost small')}${c(tr('join'),'/admissions','gold small')}<button id="mobile-toggle" type="button" aria-label="Toggle mobile menu" aria-expanded="${state.mobile}" class="mobile-toggle">☰</button></div></div>${state.mobile?`<nav class="mobile-panel" aria-label="Mobile navigation">${navLinks}${a('/login',tr('login'))}${a('/demo',tr('demo'))}</nav>`:''}</header>${content}<footer class="footer"><div class="container"><div class="footergrid"><div><a href="#/" class="brand">${brand}</a><p style="max-width:290px;margin-top:18px">Strong concepts and meaningful practice in a student-friendly learning environment.</p><span style="color:#ffe167;font-size:12px">${tr('tagline')}</span></div><div><h4>DISCOVER</h4><div class="footerlinks">${a('/about','About Us')}${a('/courses','Our Courses')}${a('/universe','Learning Universe')}${a('/quiz','Quiz Club')}<a href="./study-sprint/index.html">Daily Study Sprint</a>${a('/gallery','Gallery')}</div></div><div><h4>LEARN</h4><div class="footerlinks">${a('/materials','Digital Classroom')}${a('/tests','Online Tests')}${a('/homework','Homework')}${a('/smart-path','Vision Smart Path')}${a('/doubts','Doubt Drop')}</div></div><div><h4>CONTACT & ADMISSIONS</h4><p>Near Mahamaya Temple, Bhanpuri, Raipur, Chhattisgarh, India</p><div class="footerlinks">${a('/admissions','Admission Enquiry')}${a('/demo','Demo Class Request')}${a('/contact','Contact Us')}${a('/login','Student Portal')}</div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} SAURABH’S VISION™ • Founder: Saurabh Sahu</span><div class="row">${a('/privacy','Privacy Policy')}${a('/terms','Terms & Conditions')}<span>Designed for learning. Built with care.</span></div></div></div></footer>${wa?`<a class="floating-chat" href="https://wa.me/${h(wa)}" target="_blank" rel="noopener noreferrer" aria-label="WhatsApp enquiry">✆ WhatsApp</a>`:''}`}
function mainContent(){const path=state.route;switch(path){case '/':return homepage();case '/about':return openMain(aboutPage());case '/courses':return openMain(coursePage());case '/courses/primary':return openMain(coursePage('primary'));case '/courses/secondary':return openMain(coursePage('secondary'));case '/courses/board':return openMain(coursePage('board'));case '/universe':return openMain(universePage());case '/universe/maths':case '/universe/physics':case '/universe/chemistry':case '/universe/biology':case '/universe/junior':return openMain(worldsPage(path.split('/').pop()));case '/quiz':return openMain(quizPage());case '/smart-path':return openMain(smartPathPage());case '/admissions':return openMain(formPage('admissions'));case '/demo':return openMain(formPage('demo'));case '/login':return openMain(loginPage());case '/dashboard':return openMain(dashboardPage());case '/portal/student':return openMain(dashboardPage('student'));case '/portal/parent':return openMain(dashboardPage('parent'));case '/portal/teacher':return openMain(dashboardPage('teacher'));case '/portal/admin':return openMain(dashboardPage('admin'));case '/results':return openMain(resultsPage());case '/gallery':return openMain(galleryPage());case '/contact':return openMain(contactPage());case '/materials':return openMain(materialsPage('materials'));case '/homework':return openMain(materialsPage('homework'));case '/tests':return openMain(materialsPage('tests'));case '/doubts':return openMain(materialsPage('doubts'));case '/privacy':case '/terms':return openMain(legalPage(path.slice(1)));default:return openMain(notFound())}}
function openMain(x){return `<main id="main">${x}</main>`}
function render(){document.documentElement.lang=state.lang;app.innerHTML=layout(mainContent());if(state.route==='/dashboard'||state.route.startsWith('/portal/'))fetchDashboard();loadPublicPage();}
function nav(){let path=decodeURIComponent(location.hash.slice(1)||'/').split('?')[0];if(!path.startsWith('/'))path='/';state.route=path;state.mobile=false;render();window.scrollTo({top:0,behavior:'instant'});}
function status(id,text,cls='warn'){let el=document.querySelector(id);if(el)el.innerHTML=`<div class="notice ${cls}">${h(text)}</div>`}
async function onSubmit(event){const form=event.target,id=form.id;const d=Object.fromEntries(new FormData(form).entries());if(d.website)return;
 if(id==='login-form'){event.preventDefault();if(!state.backend)return;status('#login-status','Signing in…');try{await state.backend.login(d.email,d.password);status('#login-status','Signed in. Opening your dashboard…','success');location.hash='#/dashboard'}catch(err){status('#login-status',err.code==='auth/invalid-credential'?'Invalid email or password.':err.message,'error')}return}
 if(id==='admissions-form'||id==='demo-form'){event.preventDefault();if(!state.backend){status('#form-status','Configure Firebase to activate real submissions.','error');return}if(state.busy)return;state.busy=true;status('#form-status','Submitting securely…');try{const ref=id==='admissions-form'?await state.backend.submitAdmission(d):await state.backend.submitDemo(d);form.reset();status('#form-status',`${id==='admissions-form'?'Enquiry received':'Demo request received'}! Reference: ${ref.id}. This is not an admission or confirmed booking.`,'success')}catch(err){status('#form-status',`Submission failed: ${err.message}`,'error')}finally{state.busy=false}return}
 if(id==='doubt-form'){event.preventDefault();if(!state.backend||!state.user)return;status('#doubt-status','Submitting your question…');try{const file=form.querySelector('input[type="file"]').files[0];const doc=await state.backend.submitDoubt(d,file);form.reset();status('#doubt-status',`Question saved. Reference: ${doc.id}`,'success');await loadDoubts()}catch(err){status('#doubt-status',`Could not submit: ${err.message}`,'error')}return}
 if(id==='slot-form'){event.preventDefault();try{const date=new Date(d.startAt);if(date<=new Date())throw new Error('Select a future date/time');await state.backend.writeAdmin('demoSlots',{startAt:date.toISOString(),capacity:Number(d.capacity),bookedCount:0,active:true});alert('Slot saved.');await fetchDashboard()}catch(err){alert(`Slot not saved: ${err.message}`)}return}
 if(id==='settings-form'){event.preventDefault();try{const fields=['phone','whatsapp','email','timings'];let data={};fields.forEach(k=>data[k]=String(d[k]||'').trim());await state.backend.writeSettings(data);state.settings=data;alert('Verified contact details saved.');render()}catch(err){alert(`Settings not saved: ${err.message}`)}return}
 if(id==='add-question-form'){event.preventDefault();try{const options=d.options.split('\n').map(x=>x.trim()).filter(Boolean);if(options.length!==4||!options.includes(d.answer.trim()))throw new Error('Provide exactly four options and one exact matching correct answer.');await state.backend.writeAdmin('quizQuestions',{board:d.board,grade:d.grade,subject:d.subject,chapter:d.chapter.trim(),text:d.text.trim(),kind:'mcq',options,answer:d.answer.trim(),tag:d.tag.trim(),explanation:d.explanation.trim(),published:!!d.published});alert('Question saved. Only published questions appear publicly.');await loadRemote();await fetchDashboard()}catch(err){alert(`Question not saved: ${err.message}`)}return}
 if(id==='add-content-form'){event.preventDefault();try{if(d.url&&!safeUrl(d.url))throw new Error('Only HTTPS content links are allowed.');if(['results','gallery'].includes(d.type)&&!confirm('Have you verified that you have consent and permission to publish this item?'))return;await state.backend.writeAdmin(d.type,{title:d.title.trim(),grade:d.grade,subject:d.subject,description:(d.description||'').trim(),url:d.url||'',published:!!d.published,consentVerified:['results','gallery'].includes(d.type)?true:false});alert('Content saved.');await fetchDashboard()}catch(err){alert(`Content not saved: ${err.message}`)}return}
 if(form.matches('[data-answer-doubt]')){event.preventDefault();try{await state.backend.answerDoubt(form.dataset.answerDoubt,d.answer.trim());alert('Teacher response saved.');await fetchDashboard()}catch(err){alert(`Response not saved: ${err.message}`)}}
}
function syncQuizSelect(field,value){state.quiz[field]=value;state.quiz.i=0;state.quiz.answers=[];state.quiz.completed=false;let qs=[...starterQuestions,...remoteQuestions].filter(q=>q.board===state.quiz.board);if(field==='board'){let choices=[...new Set(qs.map(q=>q.grade))];state.quiz.grade=choices.includes('6')?'6':(choices[0]||'1')}
 qs=qs.filter(q=>q.grade===state.quiz.grade);if(['board','grade'].includes(field)){state.quiz.subject=[...new Set(qs.map(q=>q.subject))][0]||'Mathematics'}
 qs=qs.filter(q=>q.subject===state.quiz.subject);if(['board','grade','subject'].includes(field))state.quiz.chapter=[...new Set(qs.map(q=>q.chapter))][0]||'';render()}
async function finishQuiz(){const qs=availableQuestions(),q=state.quiz;if(!qs.length)return;const correct=qs.filter((v,i)=>String(q.answers[i]??'').trim().toLowerCase()===String(v.answer).trim().toLowerCase()).length;const mistakes=qs.filter((v,i)=>String(q.answers[i]??'').trim().toLowerCase()!==String(v.answer).trim().toLowerCase()).map(v=>v.tag);const report={at:Date.now(),grade:q.grade,subject:q.subject,chapter:q.chapter,correct,total:qs.length,mistakes:[...new Set(mistakes)],concepts:[...new Set(qs.map(v=>v.tag))]};localStorage.setItem('sv-last-practice',JSON.stringify(report));state.quiz.completed=true;render();if(state.backend&&state.user&&state.role==='student'){try{await state.backend.savePractice({board:q.board,grade:q.grade,subject:q.subject,chapter:q.chapter,correct,total:qs.length,tags:report.mistakes});}catch(err){console.warn('Private score not saved',err);const note=document.querySelector('.score-circle')?.parentElement;if(note)note.insertAdjacentHTML('beforeend',`<div class="notice warn">Practice completed locally, but saving to your account failed: ${h(err.message)}</div>`)}}}
let physicsTimer;
function dropBall(){const ball=document.querySelector('#ball');if(!ball)return;cancelAnimationFrame(physicsTimer);const box=ball.parentElement,ground=box.clientHeight-20-8;const height=140;let start=performance.now();const g=state.gravity;function step(now){const elapsed=(now-start)/1000;const y=Math.min(height,0.5*g*100*elapsed*elapsed);ball.style.bottom=(height+20-y)+'px';if(y<height)physicsTimer=requestAnimationFrame(step)}physicsTimer=requestAnimationFrame(step)}
document.addEventListener('submit',onSubmit);
document.addEventListener('click',async event=>{const btn=event.target.closest('button');if(!btn)return;
 if(btn.id==='lang-switch'){state.lang=state.lang==='en'?'hi':'en';render();return}
 if(btn.id==='mobile-toggle'){state.mobile=!state.mobile;render();return}
 if(btn.id==='sign-out'){if(state.backend)await state.backend.logout();location.hash='#/login';return}
 if(btn.id==='dashboard-refresh'){fetchDashboard();return}
 if(btn.dataset.math){const correct=btn.dataset.math==='15';document.querySelector('#math-feedback').textContent=correct?'Correct! Three quarters of 20 = (3 × 20) ÷ 4 = 15.':'Try again: first find one quarter of 20, then multiply by three.';return}
 if(btn.dataset.junior){document.querySelector('#junior-feedback').textContent=btn.dataset.junior==='7'?'Great! Four stars plus three stars makes seven.':'Count each star again: 4 + 3 = ?';return}
 if(btn.dataset.element!==undefined){const i=Number(btn.dataset.element),el=document.querySelector('#element-info');if(el)el.innerHTML=elementInfo(i);document.querySelectorAll('[data-element]').forEach(n=>n.classList.toggle('selected',n===btn));return}
 if(btn.dataset.cell){const data={nucleus:['Nucleus','Contains genetic material and helps regulate many cell activities.'],chloroplast:['Chloroplast','Contains chlorophyll and captures light energy used in photosynthesis.'],vacuole:['Central vacuole','A large storage compartment that also helps support the plant cell.'],mitochondrion:['Mitochondrion','Releases usable energy through cellular respiration.']};document.querySelector('#cell-title').textContent=data[btn.dataset.cell][0];document.querySelector('#cell-text').textContent=data[btn.dataset.cell][1];return}
 if(btn.id==='drop-ball'){dropBall();return}
 if(btn.dataset.answer!==undefined){state.quiz.answers[state.quiz.i]=btn.dataset.answer;document.querySelectorAll('[data-answer]').forEach(x=>x.classList.toggle('selected',x===btn));return}
 if(btn.id==='quiz-next'){const numeric=document.querySelector('#numeric-answer');if(numeric)state.quiz.answers[state.quiz.i]=numeric.value.trim();if(!String(state.quiz.answers[state.quiz.i]??'').trim()){alert('Please select or enter an answer.');return}if(state.quiz.i>=availableQuestions().length-1)finishQuiz();else{state.quiz.i++;render()}return}
 if(btn.id==='quiz-prev'){state.quiz.i=Math.max(0,state.quiz.i-1);render();return}
 if(btn.id==='quiz-retry'){state.quiz.i=0;state.quiz.answers=[];state.quiz.completed=false;render();return}
 if(btn.dataset.resolveDoubt){try{await state.backend.resolveDoubt(btn.dataset.resolveDoubt);await loadDoubts()}catch(err){alert(err.message)}return}
 if(btn.dataset.adminStatus){const [name,id,newStatus]=btn.dataset.adminStatus.split('|');try{await state.backend.updateAdmin(name,id,{status:newStatus});await fetchDashboard()}catch(err){alert(err.message)}return}
 if(btn.dataset.confirmBooking){try{await state.backend.confirmBooking(btn.dataset.confirmBooking);alert('Booking confirmed in available slot.');await fetchDashboard()}catch(err){alert(`Cannot confirm: ${err.message}`)}return}
});
document.addEventListener('change',event=>{if(event.target.id==='quiz-board')syncQuizSelect('board',event.target.value);if(event.target.id==='quiz-grade')syncQuizSelect('grade',event.target.value);if(event.target.id==='quiz-subject')syncQuizSelect('subject',event.target.value);if(event.target.id==='quiz-chapter')syncQuizSelect('chapter',event.target.value);if(event.target.id==='gravity-value'){state.gravity=Number(event.target.value);const label=document.querySelector('#gravity-label');if(label)label.textContent=String(state.gravity)}});
window.addEventListener('hashchange',nav);
async function init(){nav();if(!firebaseConfig?.projectId)return;try{const mod=await import('./firebase-service.js');state.backend=mod.service;state.backend.onAuth(async user=>{state.user=user;state.role=null;if(user){try{state.role=await state.backend.role(user.uid)}catch(err){console.warn('Cannot retrieve role',err)}}render()});await loadRemote();render();}catch(err){console.error('Firebase initialization failed',err);const info=document.createElement('div');info.className='notice warn';info.style.cssText='position:fixed;bottom:13px;left:13px;max-width:380px;z-index:120';info.textContent='Firebase could not initialize. Check configuration and network access.';document.body.append(info)}}
init();
